// Compact editor and one approval record for design + rewards.
state.toolTab='레이어';state.guideBranding=false;
function rewards(){if(!state.settings.rewards)state.settings.rewards=[{name:'기프트 세트',quantity:10,probability:.3,delivery:'현장 수령'},{name:'커피 상품권',quantity:300,probability:9,delivery:'모바일 상품권'},{name:'할인 쿠폰',quantity:'무제한',probability:30,delivery:'쿠폰 코드'}];return state.settings.rewards}
function prizeSummary(){return `<div class="table-wrap"><table class="reward-summary"><thead><tr><th>경품</th><th>수량</th><th>확률</th><th>지급 방식</th></tr></thead><tbody>${rewards().map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.quantity)}</td><td>${p.probability}%</td><td>${esc(p.delivery)}</td></tr>`).join('')}</tbody></table></div><p class="mini-label mt">현장 수령 장소: ${esc(state.settings.pickup||state.basic.place||'안내 데스크')}</p>`}
function approvalSignature(){return JSON.stringify({template:state.selectedTemplate,pages:{...state.pageLayers,[state.studioPage]:state.layers},rewards:rewards(),pickup:state.settings.pickup||state.basic.place||'안내 데스크',consent:state.settings.consentText||'기본 동의 문구',frequency:state.settings.frequency||'1일 1회'})}
function invalidateApproval(){state.approved=false;state.settings.reviewRequested=false;if(state.settings.reviewApproval)state.settings.reviewApproval.status='수정됨'}
function approvalCurrent(){return !!(state.approved&&(!state.settings.reviewApproval||state.settings.reviewApproval.signature===approvalSignature()))}
startGuide=function(){const steps=[['whitelabel','브랜딩 설정',state.guideBranding],['workspace','브랜드 준비',brands.length>0],['event-basic','행사 만들기',!!state.eventName]];return `<section class="guide-top"><div class="guide-top-head"><h2>시작 가이드</h2></div><div class="guide-items">${steps.map(([r,t,done],i)=>`<a href="#${r}" class="${done?'completed':''}" ${done?'aria-label="'+t+' 완료"':''}><b>${i+1}</b><span>${t}</span>${done?'<small>완료</small>':''}</a>`).join('')}</div></section>`};
const neutralShell=shell;shell=function(body){return neutralShell(body).replaceAll('대행사 설정','브랜딩 설정')};
const neutralWhite=whitelabel;whitelabel=function(){return neutralWhite().replaceAll('대행사 이름으로 공유하세요.','공유 화면에 우리 브랜드를 담으세요.').replaceAll('대행사 이름','조직 이름').replace('클라이언트가 보는 모든 화면에 우리의 브랜드를 담습니다.','고객에게 공유하는 화면의 로고·색상·주소를 설정합니다.').replaceAll('브랜드사 화면 주소','고객 공유 화면 주소')};
const neutralHome=home;home=function(){return neutralHome().replace('대행사 전체','전체')};
function toolPanel(){return `<aside class="unified-tools"><div class="tool-tabs" role="tablist" aria-label="편집 도구">${['레이어','속성','AI 수정'].map(t=>`<button role="tab" aria-selected="${state.toolTab===t}" data-tooltab="${t}" class="${state.toolTab===t?'active':''}">${t}</button>`).join('')}</div><div class="tool-body" role="tabpanel">${state.toolTab==='레이어'?`<div class="layers-title">${state.studioPage} 화면 <span class="mini-label">${state.layers.length}개</span></div>${state.layers.map(l=>`<div class="layer-item ${l.id===state.layerId?'active':''} ${l.visible?'':'hidden-layer'}"><span class="layer-icon">${uiIcon(l.id==='game'?'game':l.id==='button'?'button':'text')}</span><button class="layer-select" data-layer="${l.id}">${esc(l.name)}</button><button data-togglelayer="${l.id}" aria-label="${l.name} 표시 전환">${uiIcon(l.visible?'eye':'hidden')}</button><button class="layer-grip" draggable="true" data-drag-layer="${l.id}" aria-label="${l.name} 순서 이동" title="드래그로 순서 이동 · Alt+방향키">${uiIcon('grip')}</button></div>`).join('')}<p class="layers-help">요소를 선택하면 속성 탭에서 편집할 수 있습니다.</p>`:state.toolTab==='속성'?`<div id="layer-properties" class="properties-panel">${properties()}</div>`:`<div class="ai-tool"><h3>제목 수정</h3><p class="mini-label">예: 제목을 “오늘의 작은 선물”로 바꿔줘.</p><textarea id="studio-prompt" aria-label="AI 수정 요청" placeholder="수정할 제목을 따옴표로 입력하세요.">${esc(state.aiPrompt||'')}</textarea><button class="btn secondary wide mt" data-studio="ai">수정 초안 만들기</button>${state.aiLayerDraft?`<div class="ai-change mt"><span class="mini-label">변경 전</span><p>${esc(state.layers.find(l=>l.id==='title')?.text||'')}</p><span class="mini-label">변경 후</span><p>${esc(state.aiLayerDraft)}</p><div class="inline"><button class="btn" data-studio="apply-ai">적용</button><button class="btn secondary" data-studio="discard-ai">취소</button></div></div>`:''}</div>`}</div></aside>`}
const compactEditor=editor;editor=function(prizes=false){if(prizes||state.editorTab!=='디자인')return compactEditor(prizes);return shell(`${steps('editor')}${editorSections()}<div class="studio-toolbar"><div><h2>게임 디자인</h2><span class="mini-label">${currentTemplate().title}</span></div><div class="studio-pages">${['참여 시작','게임','결과'].map(t=>`<button class="${state.studioPage===t?'active':''}" data-studiopage="${t}">${t}</button>`).join('')}</div><button class="text-link" data-studio="undo">되돌리기</button></div><div class="compact-studio"><section class="studio-canvas"><div class="canvas-caption"><span>${state.studioPage} 화면</span><span>100%</span></div><div id="layer-canvas">${layerCanvas()}</div></section>${toolPanel()}</div><div class="studio-bottom"><a href="#templates" class="text-link">템플릿 변경</a><div class="inline"><button class="btn secondary" data-action="save">저장</button><button class="btn" data-action="to-review">검토 요청</button></div></div>`)};
prizeForm=function(){const sum=rewards().reduce((s,p)=>s+Number(p.probability),0);return `<p class="sub mt">경품과 지급 방식은 게임 시안과 함께 검토됩니다.</p><div class="table-wrap"><table><thead><tr><th>경품</th><th>수량</th><th>확률</th><th>지급 방식</th></tr></thead><tbody>${rewards().map((p,i)=>`<tr><td><input data-reward="${i}" data-key="name" value="${esc(p.name)}" aria-label="${i+1}번 경품 이름"></td><td><input data-reward="${i}" data-key="quantity" value="${esc(p.quantity)}" aria-label="${p.name} 수량"></td><td><div class="probability-field"><input class="probability" data-reward="${i}" data-key="probability" type="number" min="0" max="100" step="0.1" value="${p.probability}" aria-label="${p.name} 확률"><span>%</span></div></td><td><select data-reward="${i}" data-key="delivery" aria-label="${p.name} 지급 방식">${['현장 수령','모바일 상품권','쿠폰 코드'].map(t=>`<option ${p.delivery===t?'selected':''}>${t}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div><div class="between mt"><strong>당첨 확률 합계 <span id="prob-total">${sum.toFixed(1)}%</span></strong><span class="dim">미당첨 <strong id="prob-none">${Math.max(0,100-sum).toFixed(1)}%</strong></span></div><div id="prob-error" class="alert mt" ${sum>100?'':'hidden'}>확률 합계는 100% 이하여야 합니다.</div>`};
function approvalReceipt(){return `<div class="approval-receipt"><strong>${approvalCurrent()?'확정 완료':'검토 필요'}</strong><span>게임 화면 · 경품 · 지급 방식</span>${approvalCurrent()?`<small>${esc(state.settings.reviewApproval?.time||'현재 시안')} 기준</small>`:''}</div>`}
review=function(){return shell(`${steps('review')}<div class="review-heading"><div><h2>시안·경품 검토</h2><p class="sub mt">게임 화면과 경품 지급 설정을 함께 확인합니다.</p></div>${approvalReceipt()}</div><div class="grid cols-2"><section class="panel"><div class="panel-head"><h2>게임 화면</h2><div class="studio-pages">${['참여 시작','게임','결과'].map(t=>`<button data-studiopage="${t}" class="${t===state.studioPage?'active':''}">${t}</button>`).join('')}</div></div><div class="preview-panel">${phone()}</div><a class="text-link mt" style="display:inline-block" href="#editor" data-editsection="디자인">게임 수정</a></section><section class="panel"><div class="panel-head"><h2>경품·지급 방식</h2></div>${prizeSummary()}<a class="text-link" href="#prizes">설정 보기</a><div class="review-share mt"><h3>고객 검토 링크</h3><div class="inline mt"><input readonly value="${esc(location.origin+location.pathname+'#brand-review')}"><button class="btn secondary" data-action="copy-review">복사</button></div></div></section></div><div class="review-footer mt">${approvalCurrent()?`<span class="ready-check">현재 시안과 경품 설정이 확정되었습니다.</span><button class="btn" data-action="to-publish">게시 준비</button>`:`<span class="mini-label">${state.settings.reviewApproval?'수정된 내용을 다시 검토해주세요.':''}</span>`}</div>`)};
brandReview=function(){return external(`${title('',esc(state.eventName||state.basic.name||'행사 시안'),approvalCurrent()?'':'게임 화면과 경품 지급 설정을 함께 확인해주세요.','')}${approvalCurrent()?statusNotice('확정 완료','게임 화면 · 참여정보 · 경품 · 지급 방식 / '+(state.settings.reviewApproval?.time||'현재 시안')+' 기준','','게임 확정 상태'):''}<div class="grid cols-2"><section class="panel"><div class="panel-head"><h2>게임 화면</h2><div class="studio-pages">${['참여 시작','게임','결과'].map(t=>`<button data-studiopage="${t}" class="${t===state.studioPage?'active':''}">${t}</button>`).join('')}</div></div><div class="preview-panel">${phone()}</div></section><section class="panel"><h2>경품·지급 방식</h2>${prizeSummary()}${approvalCurrent()?'':`<div class="field"><label for="client-comment">수정 의견</label><textarea id="client-comment" placeholder="수정이 필요한 내용을 입력하세요."></textarea><button class="btn secondary mt" data-action="comment">의견 남기기</button></div><p class="mini-label mt">확정하면 현재 게임 화면과 경품·수량·확률·지급 방식에 대한 승인 기록을 남깁니다.</p><button class="btn wide mt" data-action="approve">시안·경품 확정</button>`}</section></div><div class="review-footer mt"><a href="#review" class="btn secondary">검토 화면으로</a>${approvalCurrent()?'<a class="btn" href="#publish">게시 준비</a>':''}</div>`)};
const originalCleanPublish=publish;publish=function(){let h=originalCleanPublish();if(state.published)return h;h=h.replace(/<div class="readiness-row"><div>시안 확정[\s\S]*?<\/div>([\s\S]*?)<\/div>/,`<div class="readiness-row"><div>시안 확정<small>게임 화면과 경품 설정을 함께 검토합니다.</small></div>${approvalCurrent()?'<span class="ready-check">확정 완료</span>':'<a href="#review" class="text-link">검토 화면 열기</a>'}</div>`);h=h.replace(/<div class="readiness-row"><div>경품과 지급 방식[\s\S]*?<\/div><a href="#prizes" class="text-link">설정 보기 →<\/a><\/div>/,`<div class="readiness-row"><div>경품·지급 방식<small>경품·수량·확률·현장 수령·모바일 지급</small></div><div class="ready-actions">${approvalCurrent()?'<span class="ready-check">확정 완료</span>':'<span class="ready-pending">검토 필요</span>'}<a href="#prizes" class="text-link">설정 보기</a></div></div>`);return h};
const approveAction=action;action=function(a,n){if(a==='approve'){if(!state.consent)return toast('참여 정보·동의 확인 후 검토를 요청해주세요.');if(rewards().some(p=>!Number.isFinite(Number(p.probability))||Number(p.probability)<0||!p.name.trim()||(p.quantity!=='무제한'&&(!Number.isFinite(Number(p.quantity))||Number(p.quantity)<0)))||rewards().reduce((s,p)=>s+Number(p.probability),0)>100)return toast('경품 이름·수량·확률을 먼저 확인해주세요.');state.settings.reviewApproval={signature:approvalSignature(),status:'확정',time:new Date().toLocaleString('ko-KR',{timeZone:'Asia/Seoul'})};state.approved=true;retainEvent();render();toast('시안과 경품·지급 방식을 확정했습니다.');return}if(a==='brand-save')state.guideBranding=true;approveAction(a,n)};
const guardedPublish=studioAction;studioAction=function(a){if(a==='publish'&&!approvalCurrent())return toast('현재 수정본의 시안·경품 검토가 필요합니다.');guardedPublish(a)};
const panelStudioBind=bindStudio;bindStudio=function(){panelStudioBind();app.querySelectorAll('[data-layer]').forEach(n=>n.onclick=()=>{state.layerId=n.dataset.layer;state.toolTab='속성';render()});};
const panelBind=bind;bind=function(){panelBind();app.querySelectorAll('[data-tooltab]').forEach(n=>n.onclick=()=>{state.toolTab=n.dataset.tooltab;render()});app.querySelectorAll('[data-layer]').forEach(n=>n.onclick=()=>{state.layerId=n.dataset.layer;state.toolTab='속성';render()});const ai=document.getElementById('studio-prompt');if(ai)ai.oninput=()=>state.aiPrompt=ai.value;app.querySelectorAll('[data-reward]').forEach(n=>{const update=()=>{const p=rewards()[+n.dataset.reward];p[n.dataset.key]=n.dataset.key==='probability'?Number(n.value):n.value;invalidateApproval();const sum=rewards().reduce((s,p)=>s+Number(p.probability),0);state.prizeError=sum>100||sum<0||rewards().some(p=>!Number.isFinite(p.probability)||p.probability<0);document.getElementById('prob-total').textContent=sum.toFixed(1)+'%';document.getElementById('prob-none').textContent=Math.max(0,100-sum).toFixed(1)+'%';document.getElementById('prob-error').hidden=!state.prizeError};n.oninput=update;n.onchange=update});const pickup=document.getElementById('pickup-location');if(pickup)pickup.oninput=()=>{state.settings.pickup=pickup.value;invalidateApproval()};const ct=document.getElementById('consent-text');if(ct){const fn=ct.oninput;ct.oninput=()=>{fn();invalidateApproval()}}const freq=document.getElementById('entry-frequency');if(freq)freq.onchange=()=>{state.settings.frequency=freq.value;invalidateApproval()}};
const neutralRender=render;render=function(){if(state.approved&&state.settings.reviewApproval&&!approvalCurrent())invalidateApproval();neutralRender();app.innerHTML=app.innerHTML.replaceAll('대행사 설정','브랜딩 설정').replaceAll('대행사 전체','전체').replaceAll('대행사 이름','조직 이름').replaceAll('대행사에 전달','담당자에게 전달');bind()};
screens.find(s=>s[0]==='whitelabel')[2]='브랜딩 설정';screens.find(s=>s[0]==='brand-review')[2]='고객 시안·경품 검토';screens.find(s=>s[0]==='review')[2]='시안·경품 검토';render();
